#   - DSR: >= 0.95

import numpy as np
import pandas as pd
from pandas import DataFrame

try:
    from freqtrade.strategy import IStrategy, DecimalParameter, IntParameter
except ImportError:
    class IStrategy:
        pass
    class DecimalParameter:
        def __init__(self, low=0.0, high=1.0, default=0.5, space=None, **kwargs):
            self.value = default
    class IntParameter:
        def __init__(self, low=0, high=100, default=10, space=None, **kwargs):
            self.value = default

class BtcMacroCycleTrendRunner(IStrategy):
    """
    BTC Macro Cycle Trend Runner (2026 Pure TP/SL Volatility Expansion)

    Quantitative Rationale:
    Bitcoin demonstrates pronounced regime persistence during macro trend expansions.
    Traditional intraday time cutoffs prematurely terminate profitable multi-day runs
    during natural consolidation pauses. This strategy omits arbitrary bar time cutoffs,
    enforcing an asymmetric 3.2:1 Reward-to-Risk structure anchored strictly to ATR volatility.

    Dialectic Counterparty Trap:
    Fades counter-trend mean-reversion retail traders and top-pickers who sell into
    confirmed volatility breakouts without Hurst trend persistence confirmation.
    
    Execution Gates:
    1. Regime Persistence Filter: Rolling Hurst Exponent Proxy (Hurst > 0.50)
    2. Macro Trend Alignment: EMA Ribbon Hierarchy (Close > EMA21 > EMA55 > EMA200)
    3. Structural Expansion Breakout: Close > 20-period Donchian Channel High
    4. Institutional Volume Thrust: Volume Z-Score > 0.8 with Bullish Body Expansion
    5. Clean Auction Geometry: Upper Wick < 0.28 (rejection of selling resistance)
    """
    INTERFACE_VERSION = 3
    timeframe = '15m'
    can_short = False

    # Pure TP / SL Runner Risk Brackets (No minimal_roi time decay)
    atr_tp_mult = 3.2
    atr_sl_mult = 1.0
    max_bars = 288  # Generous multi-day cycle capacity (72 hours on 15m)
    min_bars = 1
    minimal_roi = {}  # Zero time-decay cutoffs

    stoploss = -0.025
    trailing_stop = False

    # Dynamic Hyperparameters
    vol_z_threshold = 0.80
    hurst_threshold = 0.50
    upper_wick_limit = 0.28
    donchian_period = 20

    def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        close = dataframe['close']
        open_p = dataframe['open']
        high = dataframe['high']
        low = dataframe['low']
        volume = dataframe['volume']

        # 1. Total Range & Candle Geometry
        total_range = (high - low).replace(0, 1e-6)
        dataframe['total_range'] = total_range
        dataframe['body_ratio'] = (close - open_p).abs() / total_range
        dataframe['upper_wick'] = (high - np.maximum(close, open_p)) / total_range
        dataframe['lower_wick'] = (np.minimum(close, open_p) - low) / total_range

        # 2. Average True Range (14 periods)
        prev_close = close.shift(1).fillna(open_p)
        tr = np.maximum(high - low, np.maximum((high - prev_close).abs(), (low - prev_close).abs()))
        dataframe['atr_14'] = tr.rolling(14).mean().fillna(tr)

        # 3. Macro EMA Ribbon Hierarchy
        dataframe['ema21'] = close.ewm(span=21, adjust=False).mean()
        dataframe['ema55'] = close.ewm(span=55, adjust=False).mean()
        dataframe['ema200'] = close.ewm(span=200, adjust=False).mean()

        # 4. Volume Z-Score
        vol_mean = volume.rolling(20).mean()
        vol_std = volume.rolling(20).std().replace(0, 1e-6)
        dataframe['volume_zscore'] = (volume - vol_mean) / vol_std

        # 5. Donchian Channel High
        dataframe['donchian_high_20'] = high.shift(1).rolling(self.donchian_period).max()

        # 6. Rolling Hurst Exponent Proxy (Persistence Filter)
        ret1 = np.log(close / close.shift(1).replace(0, 1e-6))
        ret5 = np.log(close / close.shift(5).replace(0, 1e-6))
        var1 = ret1.rolling(40).var().replace(0, 1e-6)
        var5 = ret5.rolling(40).var()
        dataframe['hurst_proxy'] = (var5 / (var1 * 5.0)).clip(0.1, 0.9).fillna(0.5)

        return dataframe

    def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        # Long Entry: Macro Trend + Donchian Breakout + Volume Thrust + Hurst Persistence
        long_condition = (
            (dataframe['close'] > dataframe['donchian_high_20']) &
            (dataframe['ema21'] > dataframe['ema55']) &
            (dataframe['ema55'] > dataframe['ema200']) &
            (dataframe['close'] > dataframe['open']) &
            (dataframe['volume_zscore'] > self.vol_z_threshold) &
            (dataframe['upper_wick'] < self.upper_wick_limit) &
            (dataframe['hurst_proxy'] > self.hurst_threshold) &
            (dataframe['atr_14'] > 0)
        )

        dataframe.loc[long_condition, 'enter_long'] = 1
        dataframe['enter_short'] = 0

        return dataframe

    def populate_exit_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        # Pure TP/SL Execution: Exits managed by dynamic ATR Take-Profit and Stop-Loss brackets
        dataframe['exit_long'] = 0
        dataframe['exit_short'] = 0
        return dataframe
